final class TraceParityTests: XCTestCase {

    // MARK: Rule case — followup-basic

    func testRuleFollowupBasic() {
        let rules = TraceRule.parse("contains Redis => followup Redis PING (RESP)")
        XCTAssertEqual(rules.count, 1)
        guard case .contains(let needle0) = rules[0].matcher else { return XCTFail("rule 0: not contains") }
        XCTAssertEqual(needle0, "redis")
        guard case .followup(let name0) = rules[0].action else { return XCTFail("rule 0: not followup") }
        XCTAssertEqual(name0, "Redis PING (RESP)")
        XCTAssertEqual(rules[0].matches(text: "Redis 7.2", port: 6379), true)
        XCTAssertEqual(rules[0].matches(text: "memcached", port: 6379), false)
    }

    // MARK: Rule case — mixed-block

    func testRuleMixedBlock() {
        let rules = TraceRule.parse("# house rules\n\ncontains nginx => tag web\nport 22 => tag ssh\ncontains openssh => stop\n")
        XCTAssertEqual(rules.count, 3)
        guard case .contains(let needle0) = rules[0].matcher else { return XCTFail("rule 0: not contains") }
        XCTAssertEqual(needle0, "nginx")
        guard case .tag(let label0) = rules[0].action else { return XCTFail("rule 0: not tag") }
        XCTAssertEqual(label0, "web")
        guard case .port(let port1) = rules[1].matcher else { return XCTFail("rule 1: not port") }
        XCTAssertEqual(port1, 22)
        guard case .tag(let label1) = rules[1].action else { return XCTFail("rule 1: not tag") }
        XCTAssertEqual(label1, "ssh")
        guard case .contains(let needle2) = rules[2].matcher else { return XCTFail("rule 2: not contains") }
        XCTAssertEqual(needle2, "openssh")
        guard case .stop = rules[2].action else { return XCTFail("rule 2: not stop") }
        XCTAssertEqual(rules[0].matches(text: "nginx/1.24", port: 80), true)
        XCTAssertEqual(rules[1].matches(text: "nginx/1.24", port: 80), false)
        XCTAssertEqual(rules[2].matches(text: "nginx/1.24", port: 80), false)
        XCTAssertEqual(rules[0].matches(text: "OpenSSH_9.3", port: 22), false)
        XCTAssertEqual(rules[1].matches(text: "OpenSSH_9.3", port: 22), true)
        XCTAssertEqual(rules[2].matches(text: "OpenSSH_9.3", port: 22), true)
        XCTAssertEqual(rules[0].matches(text: "OpenSSH_9.3", port: 80), false)
        XCTAssertEqual(rules[1].matches(text: "OpenSSH_9.3", port: 80), false)
        XCTAssertEqual(rules[2].matches(text: "OpenSSH_9.3", port: 80), true)
    }

