    // MARK: Rule case — port-and-contains

    func testRulePortAndContains() {
        let rules = TraceRule.parse("port 6379 => followup Redis PING (RESP)\ncontains redis => tag cache")
        XCTAssertEqual(rules.count, 2)
        guard case .port(let port0) = rules[0].matcher else { return XCTFail("rule 0: not port") }
        XCTAssertEqual(port0, 6379)
        guard case .followup(let name0) = rules[0].action else { return XCTFail("rule 0: not followup") }
        XCTAssertEqual(name0, "Redis PING (RESP)")
        guard case .contains(let needle1) = rules[1].matcher else { return XCTFail("rule 1: not contains") }
        XCTAssertEqual(needle1, "redis")
        guard case .tag(let label1) = rules[1].action else { return XCTFail("rule 1: not tag") }
        XCTAssertEqual(label1, "cache")
        XCTAssertEqual(rules[0].matches(text: "Redis version 7", port: 6379), true)
        XCTAssertEqual(rules[1].matches(text: "Redis version 7", port: 6379), true)
        XCTAssertEqual(rules[0].matches(text: "Redis", port: 6380), false)
        XCTAssertEqual(rules[1].matches(text: "Redis", port: 6380), true)
        XCTAssertEqual(rules[0].matches(text: "memcached", port: 6379), true)
        XCTAssertEqual(rules[1].matches(text: "memcached", port: 6379), false)
        XCTAssertEqual(rules[0].matches(text: "", port: 80), false)
        XCTAssertEqual(rules[1].matches(text: "", port: 80), false)
    }

    // MARK: Rule case — duplicates-preserved-in-order

    func testRuleDuplicatesPreservedInOrder() {
        let rules = TraceRule.parse("contains a => tag one\ncontains a => tag two")
        XCTAssertEqual(rules.count, 2)
        guard case .contains(let needle0) = rules[0].matcher else { return XCTFail("rule 0: not contains") }
        XCTAssertEqual(needle0, "a")
        guard case .tag(let label0) = rules[0].action else { return XCTFail("rule 0: not tag") }
        XCTAssertEqual(label0, "one")
        guard case .contains(let needle1) = rules[1].matcher else { return XCTFail("rule 1: not contains") }
        XCTAssertEqual(needle1, "a")
        guard case .tag(let label1) = rules[1].action else { return XCTFail("rule 1: not tag") }
        XCTAssertEqual(label1, "two")
        XCTAssertEqual(rules[0].matches(text: "a", port: 1), true)
        XCTAssertEqual(rules[1].matches(text: "a", port: 1), true)
        XCTAssertEqual(rules[0].matches(text: "b", port: 1), false)
        XCTAssertEqual(rules[1].matches(text: "b", port: 1), false)
    }

    // MARK: Analyze case — http-200-server-title-refs

    func testAnalyzeHttp200ServerTitleRefs() {
        let data = Data("HTTP/1.1 200 OK\r\nServer: nginx/1.24.0\r\nContent-Type: text/html\r\n\r\n<html><head><title>Router Admin</title></head><body>See http://192.168.4.2:8080/ui and 192.168.4.1</body></html>".utf8)
        let a = TraceAnalyzer.analyze(data: data, host: "192.168.4.20", port: 80)
        XCTAssertEqual(a.signature, "45ef56228d4e3a8a32a6b895a2c8e5cf8eca07c254e3ead7091ed774c3c1ca3d")
        XCTAssertEqual(a.firstLine, "HTTP/1.1 200 OK")
        XCTAssertEqual(a.serviceHint, "HTTP")
        XCTAssertEqual(a.references.count, 2)
        XCTAssertEqual(a.references[0].host, "192.168.4.2")
        XCTAssertEqual(a.references[0].port, 8080)
        XCTAssertEqual(a.references[1].host, "192.168.4.1")
        XCTAssertNil(a.references[1].port)
    }

