    // MARK: Analyze case — reference-extraction

    func testAnalyzeReferenceExtraction() {
        let data = Data("peers: 10.0.0.5:1883, 10.0.0.6; bad 999.10.0.1, worse 10.0.0.256; dup 10.0.0.5:1883".utf8)
        let a = TraceAnalyzer.analyze(data: data, host: "192.168.4.30", port: 49152)
        XCTAssertEqual(a.signature, "12f5bdbf37eab4230ea4e84434e16193aedb185c06d06ee06f992f97dfd49ccb")
        XCTAssertEqual(a.firstLine, "peers: 10.0.0.5:1883, 10.0.0.6; bad 999.10.0.1, worse 10.0.0.256; dup 10.0.0.5:1883")
        XCTAssertNil(a.serviceHint)
        XCTAssertEqual(a.references.count, 2)
        XCTAssertEqual(a.references[0].host, "10.0.0.5")
        XCTAssertEqual(a.references[0].port, 1883)
        XCTAssertEqual(a.references[1].host, "10.0.0.6")
        XCTAssertNil(a.references[1].port)
    }

